import { and, eq, isNull } from "drizzle-orm";
import { pendingPurchases } from "../../database/schema";
import { PendingPurchaseStatus } from "../../../shared/types/enums";
import type { PaymentProvider } from "../../../shared/types/enums";

export type PendingPurchaseRow = typeof pendingPurchases.$inferSelect;

// A purchase paid before its buyer had an account expires 30 days after
// creation if still unclaimed — the same window `TeamInvite` already uses.
const CLAIM_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;

export interface CreatePendingPurchaseInput {
  // Pre-generated by the caller (`checkout.ts`) when the provider's own
  // checkout identifier isn't known yet at insert time (Stripe: the customer
  // needs this id in its metadata *before* the Checkout Session that produces
  // `providerCheckoutId` exists). Optional so a caller with no such ordering
  // constraint can still let the column default apply.
  id?: string;
  email: string;
  planId: string;
  provider: PaymentProvider;
  providerCheckoutId: string;
}

export async function createPendingPurchase(
  input: CreatePendingPurchaseInput,
): Promise<PendingPurchaseRow> {
  const [row] = await useDB()
    .insert(pendingPurchases)
    .values({ ...input, expiresAt: new Date(Date.now() + CLAIM_WINDOW_MS) })
    .returning();
  if (!row) throw new Error("Failed to create PendingPurchase");
  return row;
}

export async function findPendingPurchaseById(
  id: string,
): Promise<PendingPurchaseRow | undefined> {
  return useDB().query.pendingPurchases.findFirst({
    where: eq(pendingPurchases.id, id),
  });
}

export async function findPendingPurchaseByProviderCheckoutId(
  providerCheckoutId: string,
): Promise<PendingPurchaseRow | undefined> {
  return useDB().query.pendingPurchases.findFirst({
    where: eq(pendingPurchases.providerCheckoutId, providerCheckoutId),
  });
}

/**
 * A purchase past `expiresAt` is treated as expired the moment anything reads
 * it — no cron sweep, matching DEC-003's preference for the simplest
 * mechanism this low-volume, rarely-read table needs. Guarded by the current
 * `status` in the `WHERE` clause so a row already `CLAIMED` or `REJECTED`
 * (both terminal, both possibly *older* than the claim window) is never
 * relabeled `EXPIRED`.
 */
export async function getPendingPurchase(
  id: string,
  now: Date = new Date(),
): Promise<PendingPurchaseRow | undefined> {
  const row = await findPendingPurchaseById(id);
  if (!row) return undefined;
  if (row.status !== PendingPurchaseStatus.PENDING || row.expiresAt > now) {
    return row;
  }
  const [expired] = await useDB()
    .update(pendingPurchases)
    .set({ status: PendingPurchaseStatus.EXPIRED })
    .where(
      and(
        eq(pendingPurchases.id, id),
        eq(pendingPurchases.status, PendingPurchaseStatus.PENDING),
      ),
    )
    .returning();
  return expired ?? row;
}

/**
 * The single write path for a webhook confirming a pending purchase's
 * subscription (mirrors `upsertSubscription`'s "one write path" rationale).
 * Guarded by `providerSubscriptionId IS NULL` so redelivery of the same or a
 * different event for the same purchase writes at most once — the return
 * value tells the caller whether *this* call is the one that should trigger
 * the claim e-mail.
 */
export async function recordConfirmedSubscription(
  id: string,
  params: { providerSubscriptionId: string; providerCustomerId: string | null },
): Promise<{ firstConfirmation: boolean }> {
  const [row] = await useDB()
    .update(pendingPurchases)
    .set({
      providerSubscriptionId: params.providerSubscriptionId,
      providerCustomerId: params.providerCustomerId,
      claimEmailSentAt: new Date(),
    })
    .where(
      and(
        eq(pendingPurchases.id, id),
        isNull(pendingPurchases.providerSubscriptionId),
      ),
    )
    .returning();
  return { firstConfirmation: Boolean(row) };
}

export async function rejectPendingPurchase(
  id: string,
  reason: string,
): Promise<void> {
  await useDB()
    .update(pendingPurchases)
    .set({ status: PendingPurchaseStatus.REJECTED, failureReason: reason })
    .where(
      and(
        eq(pendingPurchases.id, id),
        eq(pendingPurchases.status, PendingPurchaseStatus.PENDING),
      ),
    );
}

export type ClaimIneligibleReason =
  | "not_found"
  | "wrong_email"
  | "already_claimed"
  | "expired"
  | "rejected"
  | "not_confirmed";

export type ClaimEligibility =
  | { ok: true }
  | { ok: false; reason: ClaimIneligibleReason };

/**
 * Pure decision at the heart of FR-005/FR-010/NFR-001: whether `claimant`
 * (the authenticated session's e-mail) may act on `purchase` right now.
 * `not_found` and `wrong_email` are kept distinguishable here for audit, but
 * `checkout.ts` deliberately maps both to the same generic response
 * (AC-021) — a foreign or non-existent claim link must look identical.
 */
export function evaluateClaimEligibility(
  purchase: PendingPurchaseRow | undefined,
  claimantEmail: string,
): ClaimEligibility {
  if (!purchase) return { ok: false, reason: "not_found" };
  if (purchase.email !== claimantEmail) return { ok: false, reason: "wrong_email" };
  if (purchase.status === PendingPurchaseStatus.CLAIMED) {
    return { ok: false, reason: "already_claimed" };
  }
  if (purchase.status === PendingPurchaseStatus.REJECTED) {
    return { ok: false, reason: "rejected" };
  }
  if (purchase.status === PendingPurchaseStatus.EXPIRED) {
    return { ok: false, reason: "expired" };
  }
  if (!purchase.providerSubscriptionId) return { ok: false, reason: "not_confirmed" };
  return { ok: true };
}

/**
 * The atomic PENDING -> CLAIMED transition (AC-006, AC-022): a single
 * conditional `UPDATE` is what makes two concurrent or repeated claims
 * resolve to exactly one success, without a `SELECT ... FOR UPDATE` lock.
 * Always called as the last statement inside the caller's transaction
 * (`buyer-provisioning.ts`), so a `null` return rolls back whatever that
 * transaction already did — no team is left behind for a claim that lost
 * the race.
 */
export async function claimPendingPurchase(
  db: Pick<ReturnType<typeof useDB>, "update">,
  id: string,
  userId: string,
  resultTeamId: string,
): Promise<PendingPurchaseRow | null> {
  const [row] = await db
    .update(pendingPurchases)
    .set({
      status: PendingPurchaseStatus.CLAIMED,
      claimedAt: new Date(),
      claimedByUserId: userId,
      resultTeamId,
    })
    .where(
      and(
        eq(pendingPurchases.id, id),
        eq(pendingPurchases.status, PendingPurchaseStatus.PENDING),
      ),
    )
    .returning();
  return row ?? null;
}
